files.content:
:root {
  --bg: #f2f5f9;
  --card: #ffffff;
  --text: #1c2733;
  --muted: #64748b;
  --border: #d7dfe9;
  --primary: #1f6feb;
  --primary-dark: #1859c0;
  --accent: #0f766e;
  --error-bg: #fdecec;
  --error-text: #b42318;
  --radius: 14px;
  --shadow: 0 6px 20px rgba(21, 42, 68, 0.08);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC",
    "Hiragino Sans GB", "Microsoft YaHei", "Helvetica Neue", Arial, sans-serif;
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
  padding: 20px 16px 40px;
}

.app {
  width: 100%;
  max-width: 560px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.header {
  text-align: center;
  padding: 8px 0 0;
}

.header h1 {
  margin: 0;
  font-size: 1.45rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--text);
}

.subtitle {
  margin: 8px 0 0;
  color: var(--muted);
  font-size: 0.9rem;
}

.card {
  background: var(--card);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 20px 18px;
  border: 1px solid rgba(215, 223, 233, 0.7);
}

.form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field label {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text);
}

.field input {
  width: 100%;
  padding: 12px 14px;
  font-size: 1rem;
  color: var(--text);
  background: #fbfcfe;
  border: 1px solid var(--border);
  border-radius: 10px;
  outline: none;
  transition: border-color 0.18s ease, box-shadow 0.18s ease,
    background-color 0.18s ease;
  appearance: none;
  -moz-appearance: textfield;
}

.field input::-webkit-outer-spin-button,
.field input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.field input::placeholder {
  color: #a4b0bf;
}

.field input:focus {
  border-color: var(--primary);
  background: #ffffff;
  box-shadow: 0 0 0 3px rgba(31, 111, 235, 0.15);
}

.field input.invalid {
  border-color: var(--error-text);
  background: #fffafa;
}

.hint {
  font-size: 0.78rem;
  color: var(--muted);
}

.actions {
  display: flex;
  gap: 12px;
  margin-top: 4px;
}

button {
  flex: 1;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 13px 18px;
  border-radius: 10px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 0.18s ease, transform 0.06s ease,
    box-shadow 0.18s ease, color 0.18s ease;
  touch-action: manipulation;
}

button#calculate {
  background: var(--primary);
  color: #ffffff;
  box-shadow: 0 4px 12px rgba(31, 111, 235, 0.28);
}

button#calculate:hover {
  background: var(--primary-dark);
}

button#calculate:active {
  transform: translateY(1px);
}

button.secondary {
  background: #eef2f8;
  color: #3a4a5c;
  border-color: var(--border);
}

button.secondary:hover {
  background: #e2e9f3;
}

button.secondary:active {
  transform: translateY(1px);
}

button:focus-visible {
  outline: 3px solid rgba(31, 111, 235, 0.4);
  outline-offset: 2px;
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.error {
  margin: 0;
  padding: 10px 14px;
  background: var(--error-bg);
  color: var(--error-text);
  border-radius: 10px;
  border: 1px solid rgba(180, 35, 24, 0.25);
  font-size: 0.9rem;
  font-weight: 500;
}

.error[hidden] {
  display: none;
}

.results h2 {
  margin: 0 0 14px;
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text);
}

.result-list {
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.result-item {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px;
  background: #f7f9fc;
  border-radius: 10px;
  border: 1px solid #edf1f7;
}

.result-item.primary {
  background: linear-gradient(135deg, #eaf2ff 0%, #f3f8ff 100%);
  border-color: #cfe0fb;
}

.result-item dt {
  margin: 0;
  color: var(--muted);
  font-size: 0.92rem;
  font-weight: 500;
}

.result-item dd {
  margin: 0;
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
  text-align: right;
  word-break: break-all;
}

.result-item.primary dd {
  font-size: 1.5rem;
  color: var(--primary-dark);
}

.note {
  margin: 14px 0 0;
  font-size: 0.78rem;
  color: var(--muted);
}

.footer {
  text-align: center;
  color: var(--muted);
  font-size: 0.8rem;
  padding: 0 8px;
}

.footer p {
  margin: 0;
}

@media (min-width: 700px) {
  body {
    padding: 48px 24px 64px;
  }

  .app {
    max-width: 600px;
    gap: 20px;
  }

  .header h1 {
    font-size: 1.7rem;
  }

  .card {
    padding: 28px 26px;
  }

  .form {
    gap: 18px;
  }

  .field input {
    padding: 13px 16px;
  }

  .result-item dd {
    font-size: 1.25rem;
  }

  .result-item.primary dd {
    font-size: 1.7rem;
  }
}

@media (max-width: 390px) {
  body {
    padding: 14px 12px 32px;
  }

  .header h1 {
    font-size: 1.25rem;
  }

  .card {
    padding: 16px 14px;
  }

  .actions {
    gap: 10px;
  }

  button {
    padding: 12px 12px;
    font-size: 0.95rem;
  }

  .result-item {
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
  }

  .result-item dd {
    text-align: left;
    font-size: 1.1rem;
  }

  .result-item.primary dd {
    font-size: 1.4rem;
  }
}

(function () {
  'use strict';

  var form = document.getElementById('loan-form');
  var principalInput = document.getElementById('principal');
  var rateInput = document.getElementById('annual-rate');
  var monthsInput = document.getElementById('months');
  var calculateBtn = document.getElementById('calculate');
  var resetBtn = document.getElementById('reset');
  var errorEl = document.getElementById('error');
  var resultsEl = document.getElementById('results');
  var monthlyEl = document.getElementById('monthly-payment');
  var interestEl = document.getElementById('total-interest');
  var totalEl = document.getElementById('total-payment');

  function formatMoney(value) {
    return value.toFixed(2);
  }

  function showError(message) {
    errorEl.textContent = message;
    errorEl.hidden = false;
    resultsEl.hidden = true;
  }

  function clearError() {
    errorEl.textContent = '';
    errorEl.hidden = true;
  }

  function parseInput(input) {
    var raw = input.value.trim();
    if (raw === '') {
      return NaN;
    }
    return Number(raw);
  }

  function calculate() {
    clearError();

    var principal = parseInput(principalInput);
    var annualRate = parseInput(rateInput);
    var months = parseInput(monthsInput);

    if (principalInput.value.trim() === '' || isNaN(principal)) {
      showError('请输入贷款本金');
      return;
    }
    if (!isFinite(principal) || principal <= 0) {
      showError('本金必须大于0');
      return;
    }
    if (rateInput.value.trim() === '' || isNaN(annualRate)) {
      showError('请输入年利率');
      return;
    }
    if (!isFinite(annualRate) || annualRate < 0) {
      showError('年利率不能为负数');
      return;
    }
    if (monthsInput.value.trim() === '' || isNaN(months)) {
      showError('请输入贷款期限');
      return;
    }
    if (!isFinite(months) || months <= 0) {
      showError('期限必须大于0个月');
      return;
    }
    if (Math.floor(months) !== months) {
      showError('期限必须为整数月');
      return;
    }

    var monthlyPayment;
    var totalPayment;
    var totalInterest;

    if (annualRate === 0) {
      monthlyPayment = principal / months;
      totalPayment = principal;
      totalInterest = 0;
    } else {
      var monthlyRate = annualRate / 100 / 12;
      var factor = Math.pow(1 + monthlyRate, months);
      monthlyPayment = principal * monthlyRate * factor / (factor - 1);
      totalPayment = monthlyPayment * months;
      totalInterest = totalPayment - principal;
    }

    if (!isFinite(monthlyPayment) || !isFinite(totalPayment) || !isFinite(totalInterest)) {
      showError('输入数值过大，无法计算');
      return;
    }

    monthlyEl.textContent = formatMoney(monthlyPayment);
    interestEl.textContent = formatMoney(totalInterest);
    totalEl.textContent = formatMoney(totalPayment);
    resultsEl.hidden = false;
  }

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    calculate();
  });

  resetBtn.addEventListener('click', function () {
    clearError();
    resultsEl.hidden = true;
    monthlyEl.textContent = '0.00';
    interestEl.textContent = '0.00';
    totalEl.textContent = '0.00';
  });

  [principalInput, rateInput, monthsInput].forEach(function (input) {
    input.addEventListener('input', function () {
      if (!errorEl.hidden) {
        clearError();
      }
    });
  });
})();
